#include <cstdio>
#include <generator>
#include <string>

std::generator<char> chars(const std::string& s) {
  for (char c : s) co_yield c;
}

int main() {
  auto g = chars(std::string(20, 'x'));
  for (char c : g) std::putchar(c);                       // loop 1

  for (char c : chars(std::string(20, 'y'))) std::putchar(c);  // loop 2
}

